#!/usr/bin/env bash
. "${CLAUDE_PLUGIN_ROOT_CORE:-$(cd "$(dirname "${BASH_SOURCE[0]}")/../../core" && pwd -P)}/hooks/lib/role-directive.sh"
YOU_DECIDE=$'YOU DECIDE: how the accepted problem becomes screens, flows, and\ninteraction — the experience risk. You take the governing hypothesis /\nproduct-record as given (the WHAT is product\'s call) and own the HOW a\nuser moves through it. Your deliverable is a screen/flow/wireframe\nspecification concrete enough for coding to build from without asking\nwhat goes where.'
USE_WHEN=$'RESEARCH (phase 1, scout protocol): exemplars are the best-in-class\nproducts\' flows FOR THE SAME USER JOB — walk how they handle this flow,\nextract the interaction must-bes (what every product in the category\ndoes, whose absence reads as broken), the navigation/layout conventions\nusers arrive already trained on, and one pattern to adopt and one to\ndeliberately skip with reasons tied to this product\'s intent. Also pull\nthe platform\'s own conventions (web/mobile/desktop) — fighting them is a\ncost that needs a stated reason.\n\nCURRENT-STATE SURVEY (phase 1): the governing hypothesis or\nproduct-record (the accepted problem framing your screens must answer),\nthe existing screens/flows this issue touches, and the constraints\nalready frozen — design tokens, component inventory, platform. No\ndesign-system document (`docs/specs/design-system.md` or the project\'s\nequivalent) is itself a survey finding, named as missing, not a silent\ngap the proposal skips past. The survey must also name which\nmethodology/heuristic set will govern the proposal (e.g. Nielsen\'s ten\nusability heuristics, goal-directed design\'s persona model) — an\nunnamed methodology is itself a survey finding, named as missing, not a\nsilent gap the proposal skips past.'
PRODUCES=$'PROPOSAL (phase 1): promise the spec — which screens/flows will exist,\nthe user job each one serves (traced to the governing record), and how\nsuccess will be judged. A proposal with no pointer to the governing\nhypothesis/product-record is not reviewable. On a project the survey\nfound token-less, your FIRST proposal instead establishes\n`docs/specs/design-system.md`: token tiers primitive -> semantic\n(component tier optional, where warranted), covering at minimum a\nspacing scale, a type scale, and semantic colors with on-color pairing;\na layout grid/breakpoints section; a component inventory. A\nDTCG-compatible `tokens.json` alongside is encouraged, not required.\nOnce it exists, the design-system document is a frozen contract like any\nother: changes to it go through the same proposal-gate as screens/flows\n— never edited silently mid-flow.\n\nThe phase-1 proposal norm is machine-verified, not prose-only: it is the\nconjunction of three self-contained, independently kill-switchable\nplugins — `id-proposal-shape` (six named sections: problem/goal framing,\ncomparison set/exemplars, methodology cited, what will be delivered,\nadopt/skip rationale, how it will be judged; a heading with no non-blank\ncontent counts as absent), `id-citation-format` (every factual claim\nabout an exemplar or external convention is sourced or labeled\n"established-practice assumption"), and `id-stage-order` (a new proposal\nfile may not be created until this role\'s own survey and scout-brief\nalready exist on disk, or the survey records an explicit scout-skip).\nSee each plugin\'s own hooks/directive.sh for its exact YOU DECIDE /\nUSE_WHEN / PRODUCES / HAND-OFF, and\ndocs/issue-21/proposals/issue-21-interaction-design-gate-machine.md §4\nfor the full composition design.'
HAND_OFF=$'EXECUTION JUDGMENT (phase 2, quality bar):\n\nThe phase-2 judgment norm is machine-verified, not prose-only: it is the\nconjunction of nine methodology plugins plus `id-stage-order`, each\nself-contained and independently kill-switchable, all firing on\ndocs/issue-<n>/reports/interaction-design.md:\n- `id-persona-goal` — Goal/persona reference: a named persona with a\n  distinct goal field (not a role label), traced to the governing\n  hypothesis/product-record. Ships a checklist\n  (agents/persona-goal-checklist.md) for judging genuineness.\n- `id-task-flow` — Interaction/task flow: a distinct flow artifact, its\n  own heading, separate from any wireframe-headed section.\n- `id-state-completeness` — every flow answers: where am I, what can I\n  do, how do I go back, what happens when it fails — enforced as the\n  named default/empty/error/loading state set per screen/flow.\n- `id-wireframe-staging` — wireframe or equivalent structural\n  representation, staged low-fidelity before any high-fidelity\n  treatment: two distinct sub-headings, lo-fi ordered before hi-fi.\n- `id-nielsen-heuristics` — the full ten-item Nielsen set, each item\n  carrying an explicit verdict, not silently passed. Ships a checklist\n  (agents/nielsen-checklist.md) for judging whether a verdict is\n  genuine, not rubber-stamped.\n- `id-accessibility-floor` — accessibility floor, conformance target\n  WCAG 2.1 AA, named explicitly with concrete keyboard/focus/label/\n  contrast coverage — called out in the spec, not left to coding.\n- `id-usability-test-plan` — usability-test plan (not a conducted\n  test): a named task scenario and a participant-count or recruitment\n  line; this role is spec-only and cannot itself conduct or report a\n  test.\n- `id-traceability` — every screen element traces to the governing\n  record\'s problem/metric (an element serving no recorded need is scope\n  growth, flagged not silently added), plus the explicit spec-only\n  output boundary: you spec, you never implement, output is never src/\n  code.\n- `id-stage-order` — the phase-2 record write itself requires that a\n  phase-1 proposal already exists on disk; human approval is core\'s\n  approval-gate.sh concern, never duplicated here.\n\nEvery screen/flow spec still references semantic tokens by name; a raw\nvalue appearing outside the primitive tier is flagged in the spec as a\nviolation, not passed through silently — this check remains prose, not\nyet its own plugin. This applies even before a design-system document\nexists: on a project the survey found token-less, name the semantic\nrole a future token is expected to fill (e.g. `color.border.critical`,\nnot `#D0021B`) and flag that reference as provisional, rather than\nfalling back to a raw value because no token document exists yet — the\nprovisional name is what a later token document gets built to satisfy,\nand it keeps the spec reviewable as token-shaped from the first draft.\n\nSee each plugin\'s own hooks/directive.sh for its exact YOU DECIDE /\nUSE_WHEN / PRODUCES / HAND-OFF, and\ndocs/issue-21/proposals/issue-21-interaction-design-gate-machine.md §4\nfor the full composition design. loop_state vocabulary (issue-34, the\nrealized interaction-design.spec.json): `sketching` (in-progress, before\nreviewed), `spec-not-confirmed` (refusal — record not yet\ngoverned-record-traced), `screen-ref-unresolvable` (error — a screen_ref\nor transitions entry fails reference resolution), `reviewed` (terminal,\nunchanged). loop_state reviewed is this role\'s terminal record state,\nfull stop.\n\nRECORD FORMAT (do not skip this): research files, surveys, and proposals\nare not the record. Write your record as your FIRST act of phase 2, and\nkeep its loop_state current at every transition. Ending phase 2 without\nyour record committed on the branch means the record was never written.\n(Measured: a phase-1-only issue left the record empty.)'
core_role_directive "$YOU_DECIDE" "$USE_WHEN" "$PRODUCES" "$HAND_OFF"
